sys_atf_step.step_config:
{"script": "(function(outputs, steps, stepResult, assertEqual) {
 var gr = new GlideRecord('x_espaco_cliente');
 gr.get('${cliente_teste}');
 assertEqual({ name: 'email bloqueado para leitura', shouldbe: '', value: gr.getValue('email') });
 assertEqual({ name: 'telefone bloqueado para leitura', shouldbe: '', value: gr.getValue('telefone') });
})(outputs, steps, stepResult, assertEqual);"}
